"""Game translations for the five Virtual Villagers games: what text each game has, the English template a
translator starts from, the installed translations and which one each game uses.

The file format itself is game-neutral (src/vv_translation_format.py, docs/translation-file-format.md).  This
module is the Virtual Villagers side:

* The INVENTORY of every string a player sees (data/translations/vv<N>_strings.json, generated by
  scripts/build_translations_inventory.py).  It holds keys, addresses, notes and the stock English's hash,
  never the games' own words: the English template is read from the player's own game when it is made.
  - "table/<id>": A New Home's and The Lost Children's string tables in the executable;
  - "sm/<eName>": The Secret City's, The Tree of Life's and New Believers' string tables (the executable's
    built-in English, replaced by Assets\\sm.xml where the game has one -- the patcher's Optional Text Changes
    and Guardians of Isola rewrite it);
  - "exe/0x<va>": the few visible literals outside the tables (button words, version lines, formats);
  - "vvfp.<part>/<id>": the patcher's own text inside the games (data/translations/patcher_strings.json,
    the patcher's own English, shipped).
* INSTALLED translations: "translations\\vv<N>\\<code>.tsv" beside the patcher, the same layout as the public
  folder on GitHub (translations/vv<N>/<code>.tsv; the release ships the accepted ones there; "Add translation
  file..." and "Download from GitHub..." put more in).  Files of the older layout,
  "translations\\<Game title>\\<Game title> - <Language>.txt", are still read.
* The CHOICE per game: a patched game uses the file copied to "<game folder>\\Virtual Villagers Fun Patcher
  Files\\Translation\\Translation.txt", which "VVFP Translations.dll" reads when the game starts.  No file there
  means the game is exactly as without translations.
"""
from __future__ import annotations

import json
import os
import re
import shutil
import struct
import tempfile
from dataclasses import dataclass, field
from pathlib import Path

import vv_translation_format as fmt
from vv_game_text import GAME_TEXT  # the games' bytes: Windows-1252, every byte kept

ROOT = Path(__file__).resolve().parents[1]
DATA = ROOT / "data" / "translations"
# The player's installed translations, beside the patcher: "Installed translations\vv<N>\<name>.tsv" (the public
# folder's layout).  Not the repository's public translations/ folder: that one never ships with the patcher
# (the owner, 2026-11-02: "do NOT include the ai french translation in the patcher, just put it in a
# Translations folder in my repos"); its files arrive only through Download from GitHub....
TRANSLATIONS_DIR = ROOT / "Installed translations"
# Where v1.35.88 and v1.35.89 installed (translations\<Game title>\*.txt): still read, never written.
LEGACY_DIR = ROOT / "translations"
PUBLIC_FOLDER = "translations"           # the repository's public folder: translations/vv<N>/<name>.tsv
PATCHER_FILES = "Virtual Villagers Fun Patcher Files"
RUNTIME_SUBFOLDER = "Translation"
RUNTIME_FILE = "Translation.txt"
DLL_NAME = "VVFP Translations.dll"
ENGLISH = "English (original)"

TITLES = {
    1: "Virtual Villagers - A New Home",
    2: "Virtual Villagers - The Lost Children",
    3: "Virtual Villagers - The Secret City",
    4: "Virtual Villagers - The Tree of Life",
    5: "Virtual Villagers - New Believers",
}
IMAGE_BASE = 0x400000


def game_number(game) -> int:
    """1-5 from a number, "vv3", a title or a build object with .id / .title / .number."""
    if isinstance(game, int):
        return game
    for attr in ("number", "game_number"):
        value = getattr(game, attr, None)
        if isinstance(value, int) and 1 <= value <= 5:
            return value
    if isinstance(game, str):
        text = game
    else:
        text = str(getattr(game, "id", None) or getattr(game, "title", None) or game)
    if text.lower().startswith("vv") and text[2:3].isdigit():
        return int(text[2])
    for number, title in TITLES.items():
        if text.casefold() == title.casefold():
            return number
    raise ValueError(f"not a Virtual Villagers game: {game!r}")


# ---- the game's English --------------------------------------------------------------------------------

def decode_game_text(data: bytes) -> str:
    """The games' single-byte text: Windows-1252, the five bytes it leaves undefined as Latin-1."""
    return bytes(data).decode(GAME_TEXT)


class ExeImage:
    """An executable's sections mapped by virtual address (enough to read its data)."""

    def __init__(self, data: bytes):
        self.data = data
        pe = struct.unpack_from("<I", data, 0x3C)[0]
        if data[pe:pe + 4] != b"PE\0\0":
            raise ValueError("not a PE executable")
        sections = struct.unpack_from("<H", data, pe + 6)[0]
        opt = struct.unpack_from("<H", data, pe + 20)[0]
        self.base = struct.unpack_from("<I", data, pe + 24 + 28)[0]
        self.sections = []
        at = pe + 24 + opt
        for i in range(sections):
            name, vsize, va, rsize, raw = struct.unpack_from("<8sIIII", data, at + 40 * i)
            self.sections.append((va, max(vsize, rsize), raw, rsize))

    def offset(self, va: int) -> int | None:
        rva = va - self.base
        for sva, size, raw, rsize in self.sections:
            if sva <= rva < sva + size:
                delta = rva - sva
                return raw + delta if delta < rsize else None
        return None

    def dword(self, va: int) -> int:
        off = self.offset(va)
        if off is None:
            return 0
        return struct.unpack_from("<I", self.data, off)[0]

    def cstring(self, va: int, limit: int = 65536) -> bytes | None:
        off = self.offset(va)
        if off is None:
            return None
        end = self.data.find(b"\0", off, off + limit)
        return self.data[off:end] if end >= 0 else None


def load_inventory(game) -> dict:
    number = game_number(game)
    path = DATA / f"vv{number}_strings.json"
    return json.loads(path.read_text(encoding="utf-8"))


def load_patcher_strings() -> list[dict]:
    path = DATA / "patcher_strings.json"
    if not path.is_file():
        return []
    return json.loads(path.read_text(encoding="utf-8"))["strings"]


def _sm_file_texts(sm: bytes) -> bytes:
    """Assets\\sm.xml as the game's loader sees it: real CR and LF dropped, the two characters \\n a line feed."""
    return sm.replace(b"\r", b"").replace(b"\n", b"").replace(b"\\n", b"\n")


def _sm_lookup(buffer: bytes, name: str) -> bytes | None:
    """The loader's own search: the first `id="NAME"`, the text after the next '>' up to `</Text>`."""
    at = buffer.find(b'id="' + name.encode(GAME_TEXT) + b'"')
    if at < 0:
        return None
    gt = buffer.find(b">", at)
    if gt < 0:
        return None
    end = buffer.find(b"</Text>", gt + 1)
    if end < 0:
        return None
    return buffer[gt + 1:end]


def find_game_exe(folder: Path, number: int) -> Path | None:
    """The executable a folder plays: the patcher's "<title> - Modded.exe" first, else the game's own."""
    folder = Path(folder)
    title = TITLES[number]
    for name in (f"{title} - Modded.exe", f"{title}.exe"):
        candidate = folder / name
        if candidate.is_file():
            return candidate
    return None


@dataclass
class TemplateRow:
    row: fmt.Row
    rules: fmt.RowRules = field(default_factory=fmt.RowRules)
    context: str = ""


def game_english(game, exe: Path, sm_xml: Path | None = None) -> dict[str, str]:
    """`<source>/<id>` -> the English this executable (and its Assets\\sm.xml) shows, for every inventory row."""
    number = game_number(game)
    inv = load_inventory(number)
    image = ExeImage(Path(exe).read_bytes())
    out: dict[str, str] = {}
    table = inv.get("table")
    if table:
        seen = set()
        for i in range(table["count"]):
            entry = table["va"] + i * table["stride"]
            ident = image.dword(entry + table["id_offset"])
            if ident in seen:
                continue
            seen.add(ident)
            ptr = image.dword(entry + table["english_offset"])
            raw = image.cstring(ptr) if ptr else None
            if raw is not None:
                out[f"table/{ident}"] = decode_game_text(raw)
    sm = inv.get("sm")
    if sm:
        buffer = None
        if sm_xml is not None and Path(sm_xml).is_file():
            buffer = _sm_file_texts(Path(sm_xml).read_bytes())
        for i in range(sm["count"]):
            entry = sm["va"] + i * sm["stride"]
            name_raw = image.cstring(image.dword(entry + sm["name_offset"]))
            if not name_raw:
                continue
            # Two of the games' own names end in tabs ("eSayApprentice\t"): the key spells them without, as
            # VVFP Translations.dll matches them (tr_after_loader); the sm.xml search keeps the game's own name.
            name = name_raw.decode(GAME_TEXT)
            stem = f"sm/{name.rstrip()}"
            if stem in out:
                continue                       # a duplicate entry: the game uses the first
            raw = _sm_lookup(buffer, name) if buffer is not None else None
            if raw is None:
                ptr = image.dword(entry + sm["english_offset"])
                raw = image.cstring(ptr) if ptr else None
            if raw is not None:
                out[stem] = decode_game_text(raw)
    for lit in inv.get("literals", []):
        raw = image.cstring(int(lit["va"], 16))
        if raw is not None:
            out[f"exe/{lit['va'].lower()}"] = decode_game_text(raw)
    return out


def game_byte_limit(english: str) -> int:
    """The longest translation VVFP Translations.dll uses for this English (its tr_fits: three times the English
    or the English plus 64 bytes, below 224 bytes for an English below 224, at most 4,000), counted in UTF-8
    bytes as the strictest case."""
    n = len(english.encode("cp1252", errors="replace"))
    limit = max(3 * n, n + 64)
    if n < 224:
        limit = min(limit, 223)
    return min(limit, 3999)


def _rules_for(entry: dict) -> fmt.RowRules:
    return fmt.RowRules(
        subjects=dict(entry.get("subjects", {})),
        tokens=tuple(entry.get("tokens", "")),
        required_tokens=tuple(entry.get("required_tokens", ())),
        forbid_chars=entry.get("forbid_chars", ""),
        selects_allowed=entry.get("selects_allowed", True),
    )


_INTEGER_CONVERSION = re.compile(r"(?<!%)%[iu]")


def content_key(english: str) -> str:
    """The English as VVFP Translations.dll finds it: a pattern row matches the shown text, so %d, %i and %u are
    one conversion ("Set %d %s to Age 18." and "Set %u %s to Age 18." are one text)."""
    return _INTEGER_CONVERSION.sub("%d", english)


def content_shadowed(entry: dict, taken: set[str]) -> bool:
    """True for a row that would never be used, and so is left out of the template (the owner, 2026-11-03: a
    translator is never given a row that does nothing).  A text drawn by the game's text routine or a dialog is
    found by the English it shows ("content" route, scripts/scan_patch_text.py), and VVFP Translations.dll keeps
    ONE translation per English: the first row with it.  A later row with the same English -- another patcher
    row, or a game string the patch's text happens to equal -- is never reached, so it is not offered.  A row a
    companion asks for by its stem ("route": "key") and an exe patch's own text ("patch/0x<va>") are found by
    key and by address, so they are always offered, and (the DLL keeps a key row out of the content map) they
    take no English from the content rows.  `taken` holds the content keys of the rows so far; it grows."""
    if entry.get("route") == "key" or entry["stem"].startswith("patch/"):
        return False
    key = content_key(entry["english"])
    if key in taken:
        return True
    taken.add(key)
    return False


def template_rows(game, folder: Path | None = None, exe: Path | None = None) -> list[TemplateRow]:
    """Every row of the game's template, its English read from the player's own game (the patched copy when
    `folder` holds one) and the patcher's own text that game shows.  Raises FileNotFoundError when no
    executable can be found (the patcher's own rows alone are never a whole template)."""
    number = game_number(game)
    if exe is None:
        if folder is None:
            raise FileNotFoundError("Choose the game's folder first.")
        exe = find_game_exe(Path(folder), number)
        if exe is None:
            raise FileNotFoundError(f"No {TITLES[number]} executable in {folder}.")
    exe = Path(exe)
    sm_xml = exe.parent / "Assets" / "sm.xml"
    english = game_english(number, exe, sm_xml)
    inv = load_inventory(number)
    rows: list[TemplateRow] = []
    for entry in inv["rows"]:
        stem = entry["stem"]
        if stem not in english:
            continue
        text = english[stem]
        if not text.strip():
            continue
        source, _slash, ident = stem.partition("/")
        key = fmt.make_key(source, ident, text)
        rules = _rules_for(entry)
        rules.byte_limit = game_byte_limit(text)
        rows.append(TemplateRow(fmt.Row(key, text, "", entry.get("notes", "")), rules, entry.get("context", "")))
    tag = f"vv{number}"
    taken = {content_key(r.row.english) for r in rows}
    for entry in load_patcher_strings():
        if tag not in entry.get("games", ()):
            continue
        if content_shadowed(entry, taken):
            continue
        source, _slash, ident = entry["stem"].partition("/")
        key = fmt.make_key(source, ident, entry["english"])
        rules = _rules_for(entry)
        if source == "patch":
            # An exe patch's own text is replaced in place: within the English's own bytes (a longer one is
            # shown only where the Unicode Text companion draws it).
            rules.byte_limit = len(entry["english"].encode("cp1252", errors="replace"))
        rows.append(TemplateRow(fmt.Row(key, entry["english"], "", entry.get("notes", "")),
                                rules, entry.get("context", "")))
    return rows


def template_map(rows: list[TemplateRow]) -> dict[str, tuple[str, fmt.RowRules]]:
    return {r.row.key: (r.row.english, r.rules) for r in rows}


def new_translation(game, language: str, code: str, rows: list[TemplateRow]) -> fmt.TranslationFile:
    return fmt.template_file([r.row for r in rows], TITLES[game_number(game)], language, code)


# ---- installed translations ----------------------------------------------------------------------------

def game_dir(game) -> Path:
    """The game's folder of installed translations: translations/vv<N> (the public folder's layout on GitHub,
    translations/vv<N>/<code>.tsv, the release ships it as is)."""
    return TRANSLATIONS_DIR / f"vv{game_number(game)}"


def legacy_dir(game) -> Path:
    """The folder v1.35.88 and v1.35.89 installed into: translations/<Game title>/<Game title> - <Language>.txt.
    Still read (and its files still chosen, exported and deleted); nothing new is written there."""
    return LEGACY_DIR / TITLES[game_number(game)]


TRANSLATION_SUFFIXES = (".tsv", ".txt")
CODE_RE = re.compile(r"^[a-z]{2,3}(?:-[A-Za-z0-9]{2,8})*$")


def installed_name(code: str) -> str:
    """The name a translation gets: "<code>.tsv" in lowercase (the shared spec: "pt-br.tsv"); refused for a code
    that is not one (it would not be a safe file name)."""
    code = (code or "").strip()
    if not CODE_RE.match(code):
        raise fmt.FormatError(f"the @code row must be a language code such as fr or pt-BR, not {code!r}")
    return f"{code.lower()}.tsv"


def credit_slug(credit: str) -> str:
    """The credit name as a file-name part: lowercase ASCII letters, digits and hyphens (accents dropped, every
    other run of characters one hyphen, none at either end); "translator" when nothing is left."""
    import unicodedata  # noqa: PLC0415
    ascii_text = unicodedata.normalize("NFKD", credit or "").encode("ascii", "ignore").decode("ascii").lower()
    slug = re.sub(r"[^a-z0-9]+", "-", ascii_text).strip("-")
    return slug[:40].strip("-") or "translator"


def public_name(code: str, credit: str, existing: dict[str, str] | None = None) -> str:
    """The file name a translation gets in a game's folder (the public translations/vv<N>/ on GitHub and the
    player's Installed translations\\vv<N>): "<code>.tsv"; when that language is already there from someone
    else, "<code>-<credit slug>.tsv", then "-2", "-3" ... so nobody's file is overwritten.  `existing` maps each
    name already in the folder to its @translator: a file of the same code and the same credit is that
    translator's own and is updated in place."""
    base = installed_name(code)
    existing = dict(existing or {})
    stem = base[:-4]
    key = (credit or "").strip().casefold()
    slug = credit_slug(credit)
    own = re.compile(re.escape(stem) + r"(?:-" + re.escape(slug) + r"(?:-\d+)?)?\.tsv")
    for name, translator in sorted(existing.items()):
        if own.fullmatch(name) and key and (translator or "").strip().casefold() == key:
            return name
    if base not in existing:
        return base
    candidate = f"{stem}-{slug}.tsv"
    n = 2
    while candidate in existing:
        candidate = f"{stem}-{slug}-{n}.tsv"
        n += 1
    return candidate


def folder_names(folder: Path) -> dict[str, str]:
    """Every translation file name in `folder` with its @translator ("" when unreadable)."""
    out: dict[str, str] = {}
    if not Path(folder).is_dir():
        return out
    for path in Path(folder).iterdir():
        if path.suffix.lower() in TRANSLATION_SUFFIXES and path.is_file():
            try:
                out[path.name] = fmt.read_file(path).translator
            except (OSError, fmt.FormatError):
                out[path.name] = ""
    return out


def shipped_dir(game) -> Path:
    """The accepted translations the release ships: translations/vv<N> beside the patcher (the public folder's
    files, (TEST) ones left out).  Read only."""
    return LEGACY_DIR / f"vv{game_number(game)}"


def translation_dirs(game) -> list[Path]:
    """Where installed translations are read: the player's own first, then the shipped ones, then the old
    layout's."""
    return [game_dir(game), shipped_dir(game), legacy_dir(game)]


TEST_MARK = "(TEST)"


def is_test(tf: fmt.TranslationFile) -> bool:
    """A test file (the owner, 2026-11-02: "Only exclude TEST files"): its language name or its credit starts
    with "(TEST)".  It stays in the repository and never ships."""
    return any((value or "").strip().upper().startswith(TEST_MARK) for value in (tf.language, tf.translator))


def is_test_translation(path: Path) -> bool:
    try:
        return is_test(fmt.read_file(Path(path)))
    except (OSError, fmt.FormatError):
        return False


# Where an installed translation is: the player's own ("installed"), shipped with the patcher ("shipped") or the
# older layout ("legacy").  A remembered choice is "<where>/<file name>", never a bare name: a player's fr.tsv
# and a shipped fr.tsv are different files (Codex, #682).
CHOICE_KINDS = ("installed", "shipped", "legacy")


def _kind_dirs(game) -> dict[str, Path]:
    return {"installed": game_dir(game), "shipped": shipped_dir(game), "legacy": legacy_dir(game)}


def choice_id(game, path: Path | None) -> str:
    """The unambiguous identity a remembered choice stores for `path` ("" for English)."""
    if path is None:
        return ""
    path = Path(path)
    for kind, folder in _kind_dirs(game).items():
        try:
            if path.resolve().parent == folder.resolve():
                return f"{kind}/{path.name}"
        except OSError:
            continue
    return path.name


def find_installed(game, name: str) -> Path | None:
    """An installed file of `game` by its choice identity ("<where>/<name>").  A bare name (settings saved before
    the identity was stored) is looked up in the player's folder first, then the shipped one, then the old
    layout's, as it was then."""
    if not name:
        return None
    kind, slash, leaf = name.partition("/")
    if slash:
        folder = _kind_dirs(game).get(kind)
        if folder is None or not leaf or Path(leaf).name != leaf:
            return None
        path = folder / leaf
        return path if path.is_file() else None
    if Path(name).name != name:
        return None
    for folder in translation_dirs(game):
        path = folder / name
        if path.is_file():
            return path
    return None


@dataclass
class Installed:
    path: Path
    language: str
    code: str
    translator: str
    game: str

    @property
    def label(self) -> str:
        return f"{self.language}, by {self.translator}" if self.translator else self.language


def installed(game) -> list[Installed]:
    """Every readable translation for `game` in the translations folders (translations/vv<N>/*.tsv, and the
    older translations/<Game title>/*.txt), by language name."""
    number = game_number(game)
    out = []
    seen: set[tuple[str, str, str]] = set()
    shipped = shipped_dir(number)
    for folder in translation_dirs(number):
        if not folder.is_dir():
            continue
        for path in sorted(p for p in folder.iterdir() if p.suffix.lower() in TRANSLATION_SUFFIXES):
            if not path.is_file():
                continue
            try:
                tf = fmt.read_file(path)
            except (OSError, fmt.FormatError):
                continue
            if tf.game and tf.game.casefold() != TITLES[number].casefold():
                continue
            if fmt.check_info(tf, TITLES[number]):
                continue
            if folder == shipped and is_test(tf):
                continue                        # a (TEST) file in a source checkout: never offered as shipped
            ident = (tf.language.casefold(), tf.code.casefold(), tf.translator.casefold())
            if ident in seen:
                continue                        # the player's own copy (read first) wins over a shipped one
            seen.add(ident)
            out.append(Installed(path, tf.language, tf.code, tf.translator, tf.game))
    out.sort(key=lambda item: item.label.casefold())
    return out


def install_target(game, tf: fmt.TranslationFile) -> Path:
    """Where a translation is installed: Installed translations/vv<N>/<public_name> -- the same file of the
    same translator is updated, another translator's of the same language is never replaced."""
    folder = game_dir(game)
    taken = dict(folder_names(shipped_dir(game)))
    own = folder_names(folder)
    # A shipped file's name is taken unless the player's folder already holds that translator's own copy of it:
    # an added file never takes a shipped file's name for another translation (Codex, #682).
    for name, translator in own.items():
        taken[name] = translator
    return folder / public_name(tf.code, tf.translator, taken)


def install_file(game, source: Path, *, shell=None) -> Path:
    """Copy a checked translation into the translations folder as <code>.tsv (atomically, never over an
    unreadable file of the same name: that one is moved aside first).  An older-layout file is replaced only when
    it is the same translation -- the same code AND the same @translator -- and then only through the Recycle Bin
    (never a hard delete; kept when the Recycle Bin refuses).  Another translator's file stays, as a variant.
    Returns the installed path."""
    number = game_number(game)
    tf = fmt.read_file(source)
    problems = fmt.check_info(tf, TITLES[number])
    if problems:
        raise fmt.FormatError("; ".join(problems))
    target = install_target(number, tf)
    if Path(source).resolve() == target.resolve():
        return target
    _atomic_copy(Path(source), target)
    old = legacy_dir(number) / fmt.file_name(TITLES[number], tf.language)
    if old.is_file() and old.resolve() != Path(source).resolve():
        try:
            previous = fmt.read_file(old)
            same = (previous.code.casefold() == tf.code.casefold()
                    and previous.translator.strip().casefold() == tf.translator.strip().casefold())
        except (OSError, fmt.FormatError):
            same = False
        if same:
            try:
                recycle([old], shell=shell)
            except OSError:
                pass                            # no Recycle Bin: both stay (the newer one is listed first)
    return target


def _atomic_copy(source: Path, target: Path) -> None:
    target.parent.mkdir(parents=True, exist_ok=True)
    if target.exists():
        try:
            fmt.read_file(target)
        except (OSError, fmt.FormatError):
            aside = target.with_name(target.stem + " (unreadable).txt")
            n = 2
            while aside.exists():
                aside = target.with_name(f"{target.stem} (unreadable {n}).txt")
                n += 1
            os.replace(target, aside)
    fd, temp = tempfile.mkstemp(prefix=".tmp-", suffix=".txt", dir=str(target.parent))
    os.close(fd)
    try:
        shutil.copyfile(source, temp)
        os.replace(temp, target)
    except BaseException:
        try:
            os.unlink(temp)
        except OSError:
            pass
        raise


def runtime_path(game_folder: Path) -> Path:
    return Path(game_folder) / PATCHER_FILES / RUNTIME_SUBFOLDER / RUNTIME_FILE


def apply_choice(game_folder: Path, translation: Path | None) -> None:
    """Make the patched game in `game_folder` use `translation` from its next start (None: English).
    Only the patcher's own Translation folder is touched."""
    target = runtime_path(game_folder)
    if translation is None:
        if target.exists():
            target.unlink()
        return
    if not (Path(game_folder) / PATCHER_FILES).is_dir():
        raise FileNotFoundError(f"{game_folder} is not a patched game (no \"{PATCHER_FILES}\" folder). "
                                "Patch the game first.")
    _atomic_copy(Path(translation), target)


# The patcher's local settings, where the Translations window remembers each game's language
# (vv_translations_window.SETTINGS_KEY: {"vv3": {"file": "<installed file name>" or "" for English, ...}}).
SETTINGS_FILE = ROOT / "patcher_local_settings.json"
SETTINGS_KEY = "translations"


def remembered_choice(game, settings: dict | None = None, settings_file: Path | None = None):
    """The language remembered for `game`: (True, path) for a chosen installed file, (True, None) for English
    chosen, (False, None) when nothing was ever chosen (or the remembered file is gone)."""
    number = game_number(game)
    if settings is None:
        try:
            settings = json.loads(Path(settings_file or SETTINGS_FILE).read_text(encoding="utf-8"))
        except (OSError, ValueError):
            return False, None
    store = settings.get(SETTINGS_KEY) if isinstance(settings, dict) else None
    entry = store.get(f"vv{number}") if isinstance(store, dict) else None
    if not isinstance(entry, dict) or not isinstance(entry.get("file", ""), str):
        return False, None
    name = entry.get("file", "")
    if not name:
        return True, None
    path = find_installed(number, name)
    return (True, path) if path is not None else (False, None)


def apply_remembered(game, game_folder: Path, settings: dict | None = None,
                     settings_file: Path | None = None) -> Path | None:
    """After a build (Codex, #672): the patched copy in `game_folder` gets the language remembered for its game,
    so a language chosen before this copy existed is used from its first start.  Nothing ever chosen: the folder
    is left as the build made it.  Returns the translation applied (None: English or nothing)."""
    known, path = remembered_choice(game, settings, settings_file)
    if not known or not (Path(game_folder) / PATCHER_FILES).is_dir():
        return None
    apply_choice(game_folder, path)
    return path


def current_choice(game_folder: Path) -> fmt.TranslationFile | None:
    target = runtime_path(game_folder)
    if not target.is_file():
        return None
    try:
        return fmt.read_file(target)
    except (OSError, fmt.FormatError):
        return None


def export_copy(source: Path, destination: Path) -> None:
    """Export translation...: the file as it is, to where the player chose."""
    _atomic_copy(Path(source), Path(destination))


def export_many(sources, folder: Path) -> tuple[list[Path], list[str]]:
    """Export... with several files selected: each file as it is, under its own name, into `folder`; two files
    with the same name (an installed fr.tsv and a shipped one by another translator) get "name (2).ext",
    "name (3).ext"... so none overwrites another. (exported, problems)."""
    folder = Path(folder)
    done, problems = [], []
    taken: set[str] = set()
    for source in sources:
        source = Path(source)
        target = folder / source.name
        n = 1
        while target.name.casefold() in taken:
            n += 1
            target = folder / f"{source.stem} ({n}){source.suffix}"
        taken.add(target.name.casefold())
        try:
            if source.resolve() == target.resolve():
                done.append(target)
                continue
            export_copy(source, target)
            done.append(target)
        except OSError as exc:
            problems.append(f"{source.name}: {exc}")
    return done, problems


# ---- deleting: to the Recycle Bin, never a hard delete ---------------------------------------------------------

class RecycleBinUnavailable(OSError):
    """The file cannot go to the Recycle Bin (none on that drive, or Windows refused): it is left in place."""


def _shell_recycle(paths: list[Path]) -> None:
    """SHFileOperationW(FO_DELETE) with FOF_ALLOWUNDO: the files go to the Recycle Bin.  Raises
    RecycleBinUnavailable, and deletes nothing, when the drive has no Recycle Bin (SHQueryRecycleBinW fails) --
    Windows would otherwise delete them for good.  FOF_WANTNUKEWARNING makes Windows ask rather than destroy a
    file it cannot recycle."""
    import ctypes  # noqa: PLC0415
    from ctypes import wintypes  # noqa: PLC0415

    if os.name != "nt":
        raise RecycleBinUnavailable("the Recycle Bin needs Windows")
    shell32 = ctypes.WinDLL("shell32")

    class SHQUERYRBINFO(ctypes.Structure):
        _fields_ = [("cbSize", wintypes.DWORD), ("i64Size", ctypes.c_longlong), ("i64NumItems", ctypes.c_longlong)]

    class SHFILEOPSTRUCTW(ctypes.Structure):
        _fields_ = [("hwnd", wintypes.HWND), ("wFunc", wintypes.UINT), ("pFrom", ctypes.c_wchar_p),
                    ("pTo", ctypes.c_wchar_p), ("fFlags", ctypes.c_ushort), ("fAnyOperationsAborted", wintypes.BOOL),
                    ("hNameMappings", ctypes.c_void_p), ("lpszProgressTitle", ctypes.c_wchar_p)]

    query = shell32.SHQueryRecycleBinW
    query.argtypes = [ctypes.c_wchar_p, ctypes.POINTER(SHQUERYRBINFO)]
    query.restype = ctypes.c_long
    for path in paths:
        root = os.path.splitdrive(str(path))[0] + "\\"
        info = SHQUERYRBINFO()
        info.cbSize = ctypes.sizeof(SHQUERYRBINFO)
        result = query(root, ctypes.byref(info))
        if result != 0:
            raise RecycleBinUnavailable(
                f"the drive {root} has no Recycle Bin (Windows error 0x{result & 0xFFFFFFFF:08X})")
    FO_DELETE, FOF_SILENT, FOF_NOCONFIRMATION, FOF_ALLOWUNDO, FOF_NOERRORUI, FOF_WANTNUKEWARNING = (
        3, 0x4, 0x10, 0x40, 0x400, 0x4000)
    op = SHFILEOPSTRUCTW()
    op.wFunc = FO_DELETE
    op.pFrom = "\0".join(str(Path(p).resolve()) for p in paths) + "\0\0"
    op.fFlags = FOF_ALLOWUNDO | FOF_NOCONFIRMATION | FOF_SILENT | FOF_NOERRORUI | FOF_WANTNUKEWARNING
    operation = shell32.SHFileOperationW
    operation.argtypes = [ctypes.POINTER(SHFILEOPSTRUCTW)]
    operation.restype = ctypes.c_int
    result = operation(ctypes.byref(op))
    if result != 0 or op.fAnyOperationsAborted:
        raise RecycleBinUnavailable(
            f"Windows could not move the files to the Recycle Bin (error 0x{result & 0xFFFF:X})")


def recycle(paths, *, shell=None) -> None:
    """Every path to the Recycle Bin (never a hard delete); `shell` replaces the Windows call in tests."""
    paths = [Path(p) for p in paths]
    if paths:
        (shell or _shell_recycle)(paths)


def delete_installed(game, paths, *, shell=None) -> tuple[list[Path], list[str]]:
    """Delete...: the installed translations `paths` of `game` to the Recycle Bin.  Only files in the game's own
    translations folder are touched.  (deleted, problems); a refused Recycle Bin deletes nothing."""
    folders = {f.resolve() for f in translation_dirs(game)}
    chosen, problems = [], []
    for path in paths:
        path = Path(path)
        try:
            inside = path.resolve().parent in folders
        except OSError:
            inside = False
        if not inside or path.suffix.lower() not in TRANSLATION_SUFFIXES:
            problems.append(f"{path.name} is not an installed translation of {TITLES[game_number(game)]}.")
        elif not path.is_file():
            problems.append(f"{path.name} is already gone.")
        else:
            chosen.append(path)
    if not chosen:
        return [], problems
    try:
        recycle(chosen, shell=shell)
    except RecycleBinUnavailable as exc:
        return [], problems + [f"Nothing was deleted: {exc}. The files were left where they are."]
    except OSError as exc:
        return [], problems + [f"Nothing was deleted: {exc}."]
    deleted = [p for p in chosen if not p.exists()]
    problems += [f"{p.name} is still there." for p in chosen if p.exists()]
    return deleted, problems


# ---- the patcher's own windows -------------------------------------------------------------------------
#
# A patcher window that shows a game's own words (a tech name, a menu word) can show them in the language the
# player chose for that game in the Translations window: display_text(game, english).  Only for what is shown
# on screen -- never for logs or files the patcher writes, which stay in the game's English.

_display_choice: dict[int, Path | None] = {}
_display_cache: dict[int, tuple[tuple[str, int], dict[str, str]]] = {}


def set_display_choice(game, translation: Path | None) -> None:
    """The translation the patcher's windows use for `game` (None: English)."""
    number = game_number(game)
    _display_choice[number] = Path(translation) if translation else None
    _display_cache.pop(number, None)


def _display_table(number: int, path: Path) -> dict[str, str]:
    try:
        stamp = (str(path), path.stat().st_mtime_ns)
    except OSError:
        return {}
    cached = _display_cache.get(number)
    if cached is not None and cached[0] == stamp:
        return cached[1]
    table: dict[str, str] = {}
    try:
        tf = fmt.read_file(path)
    except (OSError, fmt.FormatError):
        tf = None
    if tf is not None and not fmt.check_info(tf, TITLES[number]):
        for row in tf.rows:
            if not row.translation or row.english in table:
                continue
            parts = fmt.split_key(row.key)
            if parts is None or parts[2] != fmt.english_hash(row.english):
                continue                        # the English column was edited: not this line
            if any(i.severity == "error" for i in fmt.check_row(row.english, row.translation)):
                continue                        # a line with a mistake stays English, as in the game
            try:
                table[row.english] = fmt.render(row.translation, code=tf.code)
            except fmt.SelectError:
                continue
    _display_cache[number] = (stamp, table)
    return table


def display_text(game, english: str, translation: Path | None = None) -> str:
    """`english` in the chosen language of `game` (or of `translation`), else `english` itself.  Read once per
    file and refreshed when the file changes."""
    try:
        number = game_number(game)
    except ValueError:
        return english
    path = Path(translation) if translation else _display_choice.get(number)
    if path is None:
        return english
    return _display_table(number, path).get(english, english)
